import json
import unittest
from pathlib import Path


def expected_manifest(source):
    version = str(source['version']).strip()
    if version[:1].lower() == 'v':
        version = version[1:]
    clean = lambda raw, delimiter: sorted({item.strip().lower() for item in str(raw).split(delimiter) if item.strip()})
    return {
        'schema_version': 1,
        'release': {'name': str(source['component']).strip().lower(), 'version': version},
        'enabled': str(source['enabled']).strip().lower() in {'yes', 'true', '1'},
        'owners': clean(source['owners'], '|'),
        'labels': clean(source['labels'], ','),
    }


class ReleaseManifestTests(unittest.TestCase):
    def test_every_arrived_manifest_has_an_exact_canonical_pair(self):
        for source_path in sorted(Path('legacy').glob('release_*.json')):
            with self.subTest(source=source_path.name):
                target = Path('canonical') / source_path.name
                self.assertTrue(target.is_file(), f'missing {target}')
                source = json.loads(source_path.read_text(encoding='utf-8'))
                actual = json.loads(target.read_text(encoding='utf-8'))
                self.assertEqual(actual, expected_manifest(source))


if __name__ == '__main__':
    unittest.main()
